public class ProductsController : Controller
{
    public IActionResult Details(int id)
    {
        var product = _repo.Get(id);

        ViewData["PageTitle"] = product.Name;
        ViewData["RelatedProducts"] = _repo.GetRelated(id);

        // ViewBag is a dynamic wrapper over ViewData
        ViewBag.CanReview = User.Identity.IsAuthenticated;

        return View(product);
    }
}

<!-- In Details.cshtml -->
<h1>@ViewData["PageTitle"]</h1>
@if (ViewBag.CanReview)
{
    <a asp-action="Review">Write a Review</a>
}

public class AccountController : Controller
{
    [HttpPost("login")]
    public IActionResult Login(LoginRequest request)
    {
        if (_authService.Validate(request))
        {
            TempData["SuccessMessage"] = "Login successful!";
            return RedirectToAction("Index", "Home");
        }
        TempData["ErrorMessage"] = "Invalid credentials.";
        return RedirectToAction("Login");
    }
}

<!-- In _Layout.cshtml -->
@if (TempData["SuccessMessage"] is string success)
{
    <div class="alert alert-success">@success</div>
}
@if (TempData["ErrorMessage"] is string error)
{
    <div class="alert alert-danger">@error</div>
}
